            M <= divisor;  
            quotient <= 5'b0;  
            remainder <= 2'b0;  
            done <= 0;  
            count <= 3'b0;  
        end else if (start) begin  
            if (count < 3'd5) begin  
                A <= {A[3:0], Q[count]};  
                A <= A - M;  
                if (A[4] == 1) begin  
                    A <= A + M;  
                    Q[count+1] <= 0;  
                end else begin  
                    Q[count+1] <= 1;  
                end  
                count <= count + 1;  
            end else begin  
                quotient <= Q;  
                remainder <= A[1:0];  
                done <= 1;  
            end  
        end  
    end  
endmodule

