module iir_filter (
    input clk,
    input rst,
    input signed [15:0] x, // Input signal
    output reg signed [15:0] y // Output signal
);
    parameter signed [15:0] b0 = 16'h0C00; // Coefficient for x[n]
    parameter signed [15:0] b1 = 16'h0C00; // Coefficient for x[n-1]
    parameter signed [15:0] b2 = 16'h0C00; // Coefficient for x[n-2]
    parameter signed [15:0] a1 = 16'h8000; // Coefficient for y[n-1]
    parameter signed [15:0] a2 = 16'h8000; // Coefficient for y[n-2]

    reg signed [15:0] x1, x2; // Previous inputs
    reg signed [15:0] y1, y2; // Previous outputs

    always @(posedge clk or posedge rst) begin
        if (rst) begin
            y <= 16'b0;
            x1 <= 16'b0;
            x2 <= 16'b0;
            y1 <= 16'b0;
            y2 <= 16'b0;
        end else begin
            y <= (b0 * x + b1 * x1 + b2 * x2 - a1 * y1 - a2 * y2) >>> 15; // Fixed-point multiplication and scaling
            // Update the delay elements
            x2 <= x1;
            x1 <= x;
            y2 <= y1;
            y1 <= y;
        end
    end
endmodule

