module bfs_tree (
    input wire clk,
    input wire reset,
    input wire valid,
    input wire [7:0] node_in,
    output reg [7:0] node_out,
    output reg done
);
    reg [7:0] queue [0:15]; // Queue for BFS, max 16 nodes
    reg [3:0] head, tail;
    reg [3:0] count;

    initial begin
        head = 0;
        tail = 0;
        count = 0;
        done = 0;
    end

    always @(posedge clk or posedge reset) begin
        if (reset) begin
            head <= 0;
            tail <= 0;
            count <= 0;
            done <= 0;
        end else if (valid) begin
            // Enqueue the new node
            if (count < 16) begin
                queue[tail] <= node_in;
                tail <= tail + 1;
                count <= count + 1;
            end
        end else if (count > 0) begin
            // Dequeue the node and output it
            node_out <= queue[head];
            head <= head + 1;
            count <= count - 1;
            if (count == 1) begin
                done <= 1; // All nodes have been processed
            end
        end
    end
endmodule

