module pulse_generator(
    input clk,
    input rst,
    input trigger,
    input [7:0] pulse_width,
    input [7:0] period,
    output reg pulse
);
    reg [7:0] count;
    reg state; // 0 for idle, 1 for generating pulse

    always @(posedge clk or posedge rst) begin
        if (rst) begin
            pulse <= 0;
            count <= 0;
            state <= 0;
        end else if (trigger && !state) begin
            state <= 1;
            count <= 0;
            pulse <= 1;
        end else if (state) begin
            if (count < pulse_width) begin
                count <= count + 1;
            end else if (count < (pulse_width + period)) begin
                count <= count + 1;
                pulse <= 1; // Keep pulse high during pulse width
            end else begin
                pulse <= 0;
                state <= 0; // Go back to idle after completing cycle
                count <= 0; // Reset count
            end
        end
    end
endmodule

