module pwm_generator (
    input wire clk,            // Clock input
    input wire rst,            // Reset input
    input wire [7:0] duty,     // 8-bit duty cycle input (0-255)
    output reg pwm_out         // PWM output signal
);

reg [7:0] counter;            // 8-bit counter

always @(posedge clk or posedge rst) begin
    if (rst) begin
        counter <= 8'b0;
        pwm_out <= 1'b0;
    end else begin
        counter <= counter + 1;
        if (counter < duty) 
            pwm_out <= 1'b1;   // Set high if counter is less than duty
        else 
            pwm_out <= 1'b0;   // Set low otherwise
    end
end

endmodule

