module serializer (
    input wire clk,
    input wire reset,
    input wire [7:0] parallel_in,
    output reg serial_out
);
    reg [2:0] bit_count; // 3-bit counter to track serialized bits

    always @(posedge clk or posedge reset) begin
        if (reset) begin
            serial_out <= 0;
            bit_count <= 0;
        end else begin
            if (bit_count < 8) begin
                serial_out <= parallel_in[bit_count];
                bit_count <= bit_count + 1;
            end
        end
    end
endmodule

