module watchdog_timer (  
    input wire clk,  
    input wire reset,  
    input wire watchdog_signal,  
    output reg timeout  
);  
    reg [2:0] counter; // 3-bit counter (max value 7)  

    always @(posedge clk or posedge reset) begin  
        if (reset) begin  
            counter <= 3'b000;  
            timeout <= 1'b0;  
        end else begin  
            if (watchdog_signal) begin  
                counter <= 3'b000;  
                timeout <= 1'b0;  
            end else begin  
                if (counter < 3'b111) begin  
                    counter <= counter + 1;  
                end  
                if (counter == 3'b111) begin  
                    timeout <= 1'b1;  
                end  
            end  
        end  
    end  
endmodule

