module viterbi_decoder (
    input clk,
    input reset,
    input [1:0] input_bits,
    output reg [1:0] output_bits,
    output reg valid
);
    reg [1:0] state;
    reg [1:0] next_state;
    reg [1:0] output_next;

    always @(posedge clk or posedge reset) begin
        if (reset) begin
            state <= 2'b00; // Initial state
            valid <= 0;
        end else begin
            state <= next_state;
            output_bits <= output_next;
            valid <= 1;
        end
    end

    always @(*) begin
        case (state)
            2'b00: begin
                if (input_bits == 2'b00) begin
                    next_state = 2'b00;
                    output_next = 2'b00;
                end else begin
                    next_state = 2'b01;
                    output_next = 2'b01;
                end
            end
            2'b01: begin
                if (input_bits == 2'b00) begin
                    next_state = 2'b10;
                    output_next = 2'b10;
                end else begin
                    next_state = 2'b11;
                    output_next = 2'b11;
                end
            end
            2'b10: begin
                next_state = 2'b00; // Loop back for simplification
                output_next = 2'b00;
            end
            2'b11: begin
                next_state = 2'b01; // Loop back for simplification
                output_next = 2'b01;
            end
            default: begin
                next_state = 2'b00;
                output_next = 2'b00;
            end
        endcase
    end
endmodule

