module uart_controller(  
    input clk,  
    input reset,  
    input [7:0] data_in,  
    input send,  
    output reg tx,  
    output reg [7:0] data_out,  
    output reg received  
);  

    reg [3:0] state;  
    reg [7:0] tx_buffer;  
    reg [3:0] bit_counter;  

    parameter IDLE = 0, START_BIT = 1, DATA_BITS = 2, STOP_BIT = 3;  

    always @(posedge clk or posedge reset) begin  
        if (reset) begin  
            state <= IDLE;  
            tx <= 1;  
            received <= 0;  
            data_out <= 8'b0;  
            bit_counter <= 0;  
        end else begin  
            case (state)  
                IDLE: begin  
                    if (send) begin  
                        tx_buffer <= data_in;  
                        bit_counter <= 0;  
                        state <= START_BIT;  
                    end  
                end  
                START_BIT: begin  
                    tx <= 0;  // Start bit  
                    state <= DATA_BITS;  
                end  
                DATA_BITS: begin  
                    tx <= tx_buffer[bit_counter];  
                    if (bit_counter < 7) begin  
                        bit_counter <= bit_counter + 1;  
                    end else begin  
                        state <= STOP_BIT;  
                    end  
                end  
                STOP_BIT: begin  
                    tx <= 1;  // Stop bit  
                    received <= 1;  
                    data_out <= tx_buffer;  
                    state <= IDLE;  
                end  
            endcase  
        end  
    end  
endmodule

