module serializer (
    input wire clk,
    input wire reset,
    input wire [7:0] data_in,
    output reg serial_out
);
    reg [2:0] bit_count; // Count from 0 to 7 for 8 bits

    always @(posedge clk or posedge reset) begin
        if (reset) begin
            bit_count <= 3'b000;
            serial_out <= 1'b0;
        end else if (bit_count < 3'b111) begin
            serial_out <= data_in[bit_count];
            bit_count <= bit_count + 1;
        end
    end
endmodule

