module watchdog_timer (
    input wire clk,
    input wire reset,
    output reg timeout
);
    reg [3:0] counter;

    always @(posedge clk or posedge reset) begin
        if (reset) begin
            counter <= 4'b0000;
            timeout <= 1'b0;
        end else begin
            if (counter == 4'b1111) begin
                timeout <= 1'b1; // Timeout condition
            end else begin
                counter <= counter + 1;
                timeout <= 1'b0; // Reset timeout when counting
            end
        end
    end
endmodule

