module PID_Controller #(parameter N = 8, parameter P_GAIN = 1, parameter I_GAIN = 1, parameter D_GAIN = 1) (  
    input clk,  
    input rst,  
    input [N-1:0] setpoint,  
    input [N-1:0] input_signal,  
    output reg [N-1:0] control_output  
);  

    reg [N-1:0] error;  
    reg [N-1:0] previous_error;  
    reg [N-1:0] integral;  

    always @(posedge clk or posedge rst) begin  
        if (rst) begin  
            control_output <= 0;  
            previous_error <= 0;  
            integral <= 0;  
        end else begin  
            error <= setpoint - input_signal;  
            integral <= integral + error;  
            control_output <= (P_GAIN * error) + (I_GAIN * integral) + (D_GAIN * (error - previous_error));  
            previous_error <= error;  
        end  
    end  
endmodule

