module deserializer(  
    input clk,  
    input rst,  
    input din,  
    output reg [15:0] dout  
);  
    reg [3:0] count;  

    always @(posedge clk or posedge rst) begin  
        if (rst) begin  
            dout <= 16'b0;  
            count <= 4'b0;  
        end else if (count < 16) begin  
            dout <= {din, dout[15:1]};  
            count <= count + 1;  
        end  
    end  
endmodule

