module echo_cancellation #(parameter N = 5) (  
    input clk,  
    input rst,  
    input signed [15:0] x, // Input signal  
    input signed [15:0] d, // Desired signal  
    output reg signed [15:0] y // Output signal  
);  
    reg signed [15:0] w [0:N-1]; // Filter coefficients  
    reg signed [15:0] x_history [0:N-1]; // Input history  
    integer i;  
    always @(posedge clk or posedge rst) begin  
        if (rst) begin  
            for (i = 0; i < N; i = i + 1) begin  
                w[i] <= 0;  
                x_history[i] <= 0;  
            end  
            y <= 0;  
        end else begin  
            // Shift input history  
            for (i = N-1; i > 0; i = i - 1) begin  
                x_history[i] <= x_history[i-1];  
            end  
            x_history[0] <= x;  

            // Calculate output  
            y <= 0;  
            for (i = 0; i < N; i = i + 1) begin  
                y <= y + (w[i] * x_history[i]);  
            end  

            // Update filter coefficients  
            // Simple LMS update rule  
            for (i = 0; i < N; i = i + 1) begin  
                w[i] <= w[i] + (d - y) * x_history[i];  
            end  
        end  
    end  
endmodule

