module pcie_endpoint_controller(  
    input wire clk,  
    input wire start,  
    output reg ready  
);  

reg [2:0] counter;  

always @(posedge clk) begin  
    if (start) begin  
        if (counter < 5) begin  
            counter <= counter + 1;  
            ready <= 0;  
        end else begin  
            ready <= 1;  
        end  
    end else begin  
        counter <= 0;  
        ready <= 0;  
    end  
end  

endmodule

