module chebyshev_filter(
    input wire clk,
    input wire reset,
    input wire [3:0] x_in,
    output reg [3:0] y_out
);
    reg [3:0] state [0:3]; // Store states for the filter

    always @(posedge clk or posedge reset) begin
        if (reset) begin
            state[0] <= 4'b0000;
            state[1] <= 4'b0000;
            state[2] <= 4'b0000;
            state[3] <= 4'b0000;
            y_out <= 4'b0000;
        end else begin
            state[0] <= x_in;
            state[1] <= state[0] + (state[1] >> 1); // Example operation
            state[2] <= state[1] + (state[2] >> 1); // Example operation
            state[3] <= state[2] + (state[3] >> 1); // Example operation
            y_out <= state[3]; // Output the final state
        end
    end
endmodule

