module i2c_master (
    input wire clk,
    input wire start,
    input wire [7:0] data_in,
    output reg sda,
    output reg scl
);
    reg [3:0] state;
    reg [3:0] bit_count;

    parameter IDLE = 4'b0000;
    parameter START = 4'b0001;
    parameter SEND = 4'b0010;
    parameter ACK = 4'b0011;
    parameter STOP = 4'b0100;

    always @(posedge clk) begin
        case (state)
            IDLE: begin
                sda <= 1; // Idle state SDA high
                scl <= 1; // Idle state SCL high
                if (start) begin
                    state <= START;
                end
            end
            START: begin
                sda <= 0; // Start condition
                state <= SEND;
                bit_count <= 0;
            end
            SEND: begin
                scl <= 0; // Preparing to send data
                sda <= data_in[7 - bit_count]; // Send MSB first
                state <= ACK;
            end
            ACK: begin
                scl <= 1; // Clock high for acknowledgment
                // Here you would typically check for ACK from the slave
                // For simplicity, we'll assume ACK is received
                if (bit_count < 7) begin
                    bit_count <= bit_count + 1;
                    state <= SEND; // Go back to send next bit
                end else begin
                    state <= STOP; // All bits sent, go to stop
                end
            end
            STOP: begin
                sda <= 0; // Prepare for stop condition
                scl <= 1; // Clock high
                sda <= 1; // Stop condition
                state <= IDLE; // Return to idle state
            end
            default: state <= IDLE;
        endcase
    end
endmodule

