module fractional_n_pll (
    input wire clk_in,
    input wire reset,
    input wire [7:0] fractional_value,
    output reg clk_out
);
    reg [15:0] counter;
    reg [15:0] divisor;
    reg [7:0] duty_cycle;

    initial begin
        counter = 0;
        clk_out = 0;
        divisor = 1;
        duty_cycle = 128; // Default 50% duty cycle
    end

    always @(posedge clk_in or posedge reset) begin
        if (reset) begin
            counter <= 0;
            clk_out <= 0;
        end else begin
            counter <= counter + 1;
            // Adjust divisor based on fractional value
            divisor <= (1 << fractional_value); // Divide by 2^fractional_value

            // Generate output clock
            if (counter < (divisor >> 1)) begin
                clk_out <= 1; // Set high for the duty cycle
            end else if (counter < divisor) begin
                clk_out <= 0; // Set low after half the divisor
            end

            if (counter >= divisor) begin
                counter <= 0; // Reset counter after full cycle
            end
        end
    end
endmodule

