module binary_heap (
    input wire clk,
    input wire rst,
    input wire [7:0] insert_data,
    input wire insert_en,
    output reg [7:0] min_data,
    output reg valid
);

    reg [7:0] heap [0:15]; // max 16 elements
    reg [3:0] size; // current size of the heap

    always @(posedge clk or posedge rst) begin
        if (rst) begin
            size <= 0;
            valid <= 0;
        end else if (insert_en && size < 16) begin
            heap[size] <= insert_data;
            size <= size + 1;
            valid <= 1;
        end else if (size > 0) begin
            min_data <= heap[0];
            valid <= 1;
        end else begin
            valid <= 0;
        end
    end
endmodule

